/* ============================================
   GlobalStone — Global CRE Corporate Site
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #003F2D;
  --primary-dark: #012A2D;
  --accent-gold: #C5A572;
  --accent-teal: #1A6B5A;
  --white: #FFFFFF;
  --off-white: #F7F7F5;
  --light-gray: #E6E6E6;
  --mid-gray: #999999;
  --dark-gray: #444444;
  --text: #1A1A1A;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: 'Georgia', 'Times New Roman', serif;
  --max-width: 1280px;
  --section-pad: 80px;
  --section-pad-mobile: 48px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* --- Typography --- */
h1, h2, h3, h4 { font-weight: 600; line-height: 1.2; }

h1 { font-size: clamp(2.25rem, 4vw, 3.5rem); font-family: var(--font-serif); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); font-family: var(--font-serif); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

.section-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  margin-bottom: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 2px;
  transition: all var(--transition);
  letter-spacing: 0.02em;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}
.btn-primary:hover { background: var(--primary-dark); }

.btn-accent {
  background: var(--accent-gold);
  color: var(--primary-dark);
}
.btn-accent:hover { background: #B8954F; }

.btn-outline {
  border: 2px solid var(--primary);
  color: var(--primary);
  background: transparent;
}
.btn-outline:hover { background: var(--primary); color: var(--white); }

.btn-outline-white {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline-white:hover { background: var(--white); color: var(--primary); }

.btn-text {
  padding: 0;
  color: var(--primary);
  font-weight: 600;
  gap: 6px;
}
.btn-text:hover { color: var(--accent-teal); }
.btn-text .arrow { transition: transform var(--transition); }
.btn-text:hover .arrow { transform: translateX(4px); }

.btn-white {
  background: var(--white);
  color: var(--primary);
}
.btn-white:hover { background: var(--off-white); }

/* --- Header / Navigation --- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--white);
  border-bottom: 1px solid var(--light-gray);
  transition: box-shadow var(--transition);
}

.site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.03em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg { width: 20px; height: 20px; }

/* Desktop Nav */
.main-nav { display: flex; align-items: center; gap: 0; }

.nav-item {
  position: relative;
  padding: 0 20px;
  height: 72px;
  display: flex;
  align-items: center;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--dark-gray);
  transition: color var(--transition);
}

.nav-item:hover, .nav-item.active { color: var(--primary); }

.nav-item::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 20px;
  right: 20px;
  height: 3px;
  background: var(--primary);
  transform: scaleX(0);
  transition: transform var(--transition);
}

.nav-item:hover::after, .nav-item.active::after { transform: scaleX(1); }

.nav-item .chevron {
  margin-left: 4px;
  transition: transform var(--transition);
  font-size: 0.625rem;
}

.nav-item:hover .chevron { transform: rotate(180deg); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.header-search {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--dark-gray);
  transition: color var(--transition);
}
.header-search:hover { color: var(--primary); }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--light-gray);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.25s ease;
  z-index: 100;
}

.mega-menu.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
}

.mega-menu-column h4 {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--mid-gray);
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--light-gray);
}

.mega-menu-link {
  display: block;
  padding: 10px 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--dark-gray);
  transition: all var(--transition);
  border-bottom: 1px solid transparent;
}

.mega-menu-link:hover {
  color: var(--primary);
  padding-left: 8px;
}

/* Mobile Navigation */
.mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  height: 20px;
  justify-content: center;
}

.mobile-toggle span {
  display: block;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
  transition: all var(--transition);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  overflow-y: auto;
  z-index: 999;
  padding: 24px;
}

.mobile-nav.active { display: block; }

.mobile-nav-item {
  border-bottom: 1px solid var(--light-gray);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text);
}

.mobile-accordion {
  display: none;
  padding: 0 0 16px 16px;
}

.mobile-accordion.active { display: block; }

.mobile-accordion-section { margin-bottom: 16px; }

.mobile-accordion-title {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--mid-gray);
  margin-bottom: 8px;
}

.mobile-accordion a {
  display: block;
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--dark-gray);
}

.mobile-accordion a:hover { color: var(--primary); }

/* --- Hero Sections --- */
.hero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  margin-top: 72px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  background-color: var(--primary-dark);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,63,45,0.88) 0%, rgba(1,42,45,0.72) 100%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 640px;
  padding: var(--section-pad) 0;
}

.hero-content h1 {
  color: var(--white);
  margin-bottom: 20px;
}

.hero-content p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  line-height: 1.7;
  margin-bottom: 32px;
}

.hero-small {
  min-height: 400px;
}

/* Skyline pattern for hero (CSS-only) */
.hero-pattern {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  height: 100%;
  opacity: 0.06;
  background:
    linear-gradient(to top, transparent 20%, var(--white) 20%, var(--white) 80%, transparent 80%) 0% 100% / 40px 70% no-repeat,
    linear-gradient(to top, transparent 10%, var(--white) 10%, var(--white) 90%, transparent 90%) 60px 100% / 30px 55% no-repeat,
    linear-gradient(to top, transparent 15%, var(--white) 15%, var(--white) 85%, transparent 85%) 110px 100% / 50px 85% no-repeat,
    linear-gradient(to top, transparent 20%, var(--white) 20%, var(--white) 80%, transparent 80%) 180px 100% / 35px 60% no-repeat,
    linear-gradient(to top, transparent 10%, var(--white) 10%, var(--white) 90%, transparent 90%) 230px 100% / 45px 75% no-repeat;
}

/* --- Featured Insights --- */
.featured-insights {
  padding: var(--section-pad) 0;
  background: var(--white);
}

.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.insight-card {
  border: 1px solid var(--light-gray);
  border-radius: 4px;
  overflow: hidden;
  transition: all var(--transition);
}

.insight-card:hover {
  box-shadow: 0 8px 32px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  position: relative;
  overflow: hidden;
}

.insight-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.15;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 20px,
    rgba(255,255,255,0.1) 20px,
    rgba(255,255,255,0.1) 40px
  );
}

.insight-card-body { padding: 24px; }

.insight-tag {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent-teal);
  margin-bottom: 12px;
}

.insight-card-body h3 {
  font-size: 1.125rem;
  margin-bottom: 12px;
  line-height: 1.4;
}

.insight-card-body p {
  font-size: 0.875rem;
  color: var(--dark-gray);
  line-height: 1.6;
}

.insight-date {
  font-size: 0.8125rem;
  color: var(--mid-gray);
  margin-top: 12px;
}

/* --- Announcement Banner --- */
.announcement-banner {
  background: var(--primary);
  color: var(--white);
  padding: 20px 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.announcement-inner p {
  font-size: 1.0625rem;
  font-weight: 500;
}

.announcement-inner .btn { white-space: nowrap; }

/* --- About Statement --- */
.about-statement {
  padding: var(--section-pad) 0;
  background: var(--off-white);
}

.about-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.about-visual {
  height: 400px;
  background: linear-gradient(145deg, var(--primary) 0%, var(--accent-teal) 100%);
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.about-visual::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 200px;
  height: 200px;
  border: 3px solid rgba(255,255,255,0.15);
  border-radius: 50%;
}

.about-visual::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 140px;
  height: 140px;
  border: 3px solid rgba(255,255,255,0.1);
  border-radius: 50%;
}

.about-text h2 { margin-bottom: 24px; color: var(--primary-dark); }

.about-text p {
  font-size: 1.0625rem;
  color: var(--dark-gray);
  line-height: 1.8;
  margin-bottom: 32px;
}

/* --- What We Do (Tabbed) --- */
.what-we-do {
  padding: var(--section-pad) 0;
  background: var(--white);
}

.what-we-do-inner {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 0;
  min-height: 360px;
  border: 1px solid var(--light-gray);
  border-radius: 4px;
  overflow: hidden;
}

.wwd-tabs {
  background: var(--primary-dark);
  padding: 0;
}

.wwd-tab {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 28px 32px;
  font-size: 1rem;
  font-weight: 500;
  color: rgba(255,255,255,0.6);
  border: none;
  border-left: 4px solid transparent;
  text-align: left;
  transition: all var(--transition);
  cursor: pointer;
  background: transparent;
}

.wwd-tab:hover { color: rgba(255,255,255,0.85); background: rgba(255,255,255,0.04); }

.wwd-tab.active {
  color: var(--white);
  border-left-color: var(--accent-gold);
  background: rgba(255,255,255,0.08);
}

.wwd-panels { padding: 48px; display: flex; align-items: center; }

.wwd-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.wwd-panel.active { display: block; }

.wwd-panel h3 {
  font-size: 1.75rem;
  font-family: var(--font-serif);
  color: var(--primary-dark);
  margin-bottom: 20px;
}

.wwd-panel p {
  font-size: 1.0625rem;
  color: var(--dark-gray);
  line-height: 1.8;
  margin-bottom: 28px;
}

.wwd-panel .service-list {
  margin-bottom: 28px;
}

.wwd-panel .service-list li {
  padding: 6px 0;
  font-size: 0.9375rem;
  color: var(--dark-gray);
  padding-left: 20px;
  position: relative;
}

.wwd-panel .service-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 14px;
  width: 8px;
  height: 2px;
  background: var(--accent-gold);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Newsletter --- */
.newsletter {
  padding: var(--section-pad) 0;
  background: var(--primary);
  color: var(--white);
  text-align: center;
}

.newsletter h2 { margin-bottom: 12px; color: var(--white); }

.newsletter p {
  font-size: 1.0625rem;
  color: rgba(255,255,255,0.75);
  margin-bottom: 32px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.25);
  border-radius: 2px;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 0.9375rem;
}

.newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-form input:focus { outline: none; border-color: var(--accent-gold); }

/* --- Latest Insights --- */
.latest-insights {
  padding: var(--section-pad) 0;
  background: var(--off-white);
}

.latest-insights-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 40px;
}

.insights-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.insight-list-card {
  background: var(--white);
  border-radius: 4px;
  overflow: hidden;
  transition: all var(--transition);
  border: 1px solid var(--light-gray);
}

.insight-list-card:hover {
  box-shadow: 0 8px 32px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

.insight-list-img {
  height: 180px;
  position: relative;
  overflow: hidden;
}

.insight-list-img.img-1 { background: linear-gradient(135deg, #003F2D 0%, #1A6B5A 100%); }
.insight-list-img.img-2 { background: linear-gradient(135deg, #012A2D 0%, #003F2D 100%); }
.insight-list-img.img-3 { background: linear-gradient(135deg, #1A6B5A 0%, #012A2D 100%); }

.insight-list-img::after {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.12;
  background: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 15px,
    rgba(255,255,255,0.08) 15px,
    rgba(255,255,255,0.08) 30px
  );
}

.insight-list-body { padding: 24px; }

.insight-list-body .insight-tag { margin-bottom: 8px; }

.insight-list-body h3 {
  font-size: 1rem;
  margin-bottom: 8px;
  line-height: 1.4;
}

/* --- Commitment Section --- */
.commitment {
  padding: var(--section-pad) 0;
  background: var(--white);
}

.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-top: 40px;
}

.commitment-card {
  padding: 32px;
  background: var(--off-white);
  border-radius: 4px;
  transition: all var(--transition);
  border-bottom: 3px solid transparent;
}

.commitment-card:hover {
  border-bottom-color: var(--accent-gold);
  box-shadow: 0 8px 24px rgba(0,0,0,0.06);
}

.commitment-icon {
  width: 48px;
  height: 48px;
  background: var(--primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.commitment-icon svg { width: 24px; height: 24px; color: var(--white); }

.commitment-card h3 { margin-bottom: 12px; font-size: 1.125rem; }

.commitment-card p {
  font-size: 0.9375rem;
  color: var(--dark-gray);
  line-height: 1.7;
  margin-bottom: 20px;
}

/* --- Footer --- */
.site-footer {
  background: var(--primary-dark);
  color: var(--white);
  padding: 64px 0 0;
}

.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-brand .logo { color: var(--white); margin-bottom: 16px; }

.footer-brand p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  max-width: 320px;
}

.footer-col h4 {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 6px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition);
}

.footer-legal a:hover { color: var(--white); }

/* --- Services Page --- */
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.service-card {
  padding: 40px 32px;
  background: var(--white);
  border: 1px solid var(--light-gray);
  border-radius: 4px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.service-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent-gold);
  transform: scaleX(0);
  transition: transform var(--transition);
  transform-origin: left;
}

.service-card:hover::before { transform: scaleX(1); }

.service-card:hover {
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

.service-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent-teal) 100%);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.service-card-icon svg { width: 28px; height: 28px; color: var(--white); }

.service-card h3 {
  font-size: 1.25rem;
  margin-bottom: 16px;
  color: var(--primary-dark);
